import json, sys, itertools, math
from collections import defaultdict
sys.path.insert(0, '/workspace/task_file/scripts')
from cost_model import CostModel, align, HEADS, HIDDEN

cm = CostModel(64)

def load(f):
    return [json.loads(l) for l in open(f)]

def metrics(rs, plan):
    reqs = {r['request_id']: r for r in rs}
    return cm.plan_metrics(reqs, plan)

def make_plan(rs, batches, shape_set):
    # batches: list of list of req dicts. shape_set sorted list of seq_align, choose smallest >= max align in batch
    recs = []
    for bi, batch in enumerate(batches):
        maxS = max(align(r['prompt_len'],64) for r in batch)
        seq = next(s for s in shape_set if s >= maxS)
        bid = f'b-{bi:05d}'
        for r in batch:
            recs.append({'request_id':r['request_id'],'batch_id':bid,'shape':{'seq_align':seq,'heads_align':HEADS,'hidden_align':HIDDEN}})
    return recs

def exact_sg(rs):
    groups = defaultdict(list)
    for r in rs:
        groups[(align(r['prompt_len'],64), r['gen_len'])].append(r)
    return list(groups.values())

def choose_shapes(batches, K=8):
    reqs = [r for b in batches for r in b]
    vals = sorted(set(align(r['prompt_len'],64) for r in reqs))
    if len(vals) <= K:
        return vals
    # minimize compile sum: choose K-1 smallest + max (valid, compile minimal)
    return sorted(vals[:K-1] + [vals[-1]])

def pr(name, rs, batches):
    sh = choose_shapes(batches)
    plan = make_plan(rs, batches, sh)
    m = metrics(rs, plan)
    print(name, 'nbatch',len(batches),'shapes',sh)
    print('  cost %.4e pad %.6f p95 %.4e seq %.4e' % (m['cost'],m['pad_ratio'],m['p95_latency_ms'],m['sequential_timecost']))
    return m

if __name__ == '__main__':
    for f in ['/workspace/task_file/input_data/requests_bucket_1.jsonl','/workspace/task_file/input_data/requests_bucket_2.jsonl']:
        rs=load(f)
        print('\nFILE',f)
        print('singleton batches',len(rs))
        pr('singleton', rs, [[r] for r in rs])
        pr('exact_sg', rs, exact_sg(rs))
EOF
